merge_wiring:
ch_genome_bam
    .map {
        meta, bam ->
            def meta_clone = meta.clone()
            meta_clone.remove('read_group')
            meta_clone.id = meta_clone.id - ~/_T\d+$/
            [ meta_clone, bam ]
    }
    .groupTuple(by: [0])
    .map {
        meta, bam ->
            [ meta, bam.flatten() ]
    }
    .set { ch_sort_bam }
